    function QueryStockDividend(symbol, rKey) {
        const qry = JSON.stringify({
            s: "hd",
            c: "cqyz",
            d: {
                s: symbol, // Use the provided symbol
            },
            r: "ExD" + rKey // Set r as "ExD" + rKey
        });

        setTimeout(() => {
            QryHistoryData(qry);
        }, 100); // Delay by 100ms to avoid immediate recursion
    }

    function QryHistoryData(message) {
        if (ws && ws.readyState === WebSocket.OPEN) {
            OutputMessage(103, "[WebSocket] Sent:", message);

            let bExD = 0;
            try {
                const parsedMessage = JSON.parse(message);

                if (parsedMessage.ExD) {
                    bExD = parsedMessage.ExD; // Assign ExD if it exists
                }

                const r = parsedMessage.r;
                
                if (r) {
                    // Store the r and message in historyDataMap if not already present
                    if (!historyDataMap.has(r)) {
                        historyDataMap.set(r, message);
                    }
        
                    if (bExD === 1) {
                        const s = parsedMessage.d.s;
                        if (s) {
                            //const topicPtr = C.stringToUTF8OnStack(s);
                            const len = C.lengthBytesUTF8(s) + 1;
                            const topicPtr = C._malloc(len);
                            C.stringToUTF8(s, topicPtr, len);
                            const nQryDividend = C._CoreProcHistoryData(0, topicPtr, null, 0); 
                            C._free(topicPtr);
                    
                            if (nQryDividend === 1) {
                                QueryStockDividend(s, r); // Call QueryStockDividend with a delay
                                return;
                            }
                        }                                                
                    } else {
                        // Increment the query count for the r key
                        const currentCount = queryCountMap.get(r) || 0;
                        queryCountMap.set(r, currentCount + 1);                        
                    }
                }
            } catch (error) {
                OutputMessage(103, "Failed to parse message or extract 'r': " + error);
            }

            ws.send(message);
            SendSubscribeCount(1, message);
        } else {
            OutputMessage(101, "[WebSocket] Cannot send, not connected.");
        }
    }

    async function CommodityVersion(sbjct){
        let bRoot = true;
        let streamName = sbjct.replaceAll('.', '_');
        if (sbjct.startsWith("dq2.info")) {
            streamName = "dq2_info";
            if (sbjct !== "dq2.info") {
                bRoot = false;
            }
        }
        const streamInfo = await jsm.streams.info(streamName);
        const lastTime = streamInfo.state.last_ts;
        let messageCount = 0;
        let Count = 0;

        if (bRoot) {
            messageCount = streamInfo.state.messages;
        } else {

            const apiSubject = `$JS.API.STREAM.INFO.${streamName}`;
            const requestPayload = JSON.stringify({subjects_filter: ">"});
            const responseMsg = await NC.request(apiSubject, requestPayload, { timeout: 5000 });
            const bytes = Uint8Array.from(responseMsg.data);
            const decoder = new TextDecoder('utf8');
            const jsonString = decoder.decode(bytes);
            const responseData = JSON.parse(jsonString);
            const allSubjects = Object.keys(responseData.state.subjects || {});
            messageCount = allSubjects.filter(subject => subject.startsWith(sbjct + ".")).length;
        }
        OutputMessage(103, `${sbjct} 下 subject 數量: ${messageCount}, ${Count}, lastTime: ${lastTime}`);
        onCommodityVersionCallback(sbjct, messageCount, lastTime);
    }

    function GetCommodityVersion(subject) {        
        CommodityVersion(subject);
    }
  
