    function SearchContract(types, keyword, unikey) {
        // types 可為 'S' 或 'S,F,O' 或 ['S','F','O']
        let typeArr;
        if (Array.isArray(types)) {
            typeArr = types;
        } else if (typeof types === 'string') {
            typeArr = types.split(',').map(s => s.trim()).filter(Boolean);
        } else {
            typeArr = [];
        }
        
        const json = JSON.stringify({
            s: 'quote2',
            c: 'search',
            r: unikey,
            d: {
                symbol: keyword,
                type: typeArr
            }
        });

        if (ws && ws.readyState === WebSocket.OPEN) {
            OutputMessage(103, "[WebSocket] Sent:", json);
            ws.send(json);
            SendSubscribeCount(2, json);
        } else {
            OutputMessage(101, "[WebSocket] Cannot send, not connected.");
        }
    }

